package com.citacloud.springboot.contacloud.app.views;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.security.TenantContext;import com.citacloud.springboot.contacloud.app.services.*;import com.citacloud.springboot.contacloud.app.views.components.*;import com.vaadin.flow.component.*;import com.vaadin.flow.component.checkbox.Checkbox;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.dialog.Dialog;import com.vaadin.flow.component.grid.ColumnTextAlign;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.notification.Notification;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.textfield.TextField;import com.vaadin.flow.router.*;import jakarta.annotation.security.PermitAll;import java.math.*;import java.util.*;
@Route(value="configuracion/facturacion/recargos",layout=MainLayout.class) @PageTitle("Configuración de recargos | ContaCloud") @PermitAll
public class ConfiguracionRecargosView extends VerticalLayout implements BeforeEnterObserver {private final ConfiguracionRecargoService service;private ConfiguracionRecargoDto datos;private boolean integrada;private final Checkbox habilitado=new Checkbox("Permitir recargos en facturación"),venta=new Checkbox("Permitir recargo general de la venta"),linea=new Checkbox("Permitir recargo por producto"),porcentaje=new Checkbox("Permitir recargo por porcentaje"),monto=new Checkbox("Permitir recargo por monto"),motivo=new Checkbox("Requerir motivo"),autorizacion=new Checkbox("Permitir autorización superior");private final AppGrid<ConfiguracionRecargoDto.Limite> gridLimites=new AppGrid<>(ConfiguracionRecargoDto.Limite.class);private final AppGrid<ConfiguracionRecargoDto.Tipo> gridTipos=new AppGrid<>(ConfiguracionRecargoDto.Tipo.class);private final AppGrid<ConfiguracionRecargoDto.Motivo> gridMotivos=new AppGrid<>(ConfiguracionRecargoDto.Motivo.class);
 public ConfiguracionRecargosView(ConfiguracionRecargoService s){service=s;addClassNames("cc-page","cc-surcharge-config-page");setWidthFull();setPadding(true);habilitado.addValueChangeListener(e->disponibilidad());}
 @Override public void beforeEnter(BeforeEnterEvent e){e.forwardTo(ConfiguracionDescuentosRecargosView.class);}
 public void prepararIntegrada(){integrada=true;removeClassName("cc-page");setPadding(false);construir();}
 private void construir(){removeAll();try{datos=service.obtener();if(integrada)add(politica(),limites(),tipos(),motivos());else add(new AppPageHeader("Configuración de recargos","Define políticas, tipos, límites por rol y motivos utilizados en Facturación."),politica(),limites(),tipos(),motivos());}catch(RuntimeException ex){error(ex,"No fue posible cargar la configuración de recargos.");}}
 private Component politica(){cargar();boolean editable=can("recargos_configuracion.editar");for(Checkbox c:campos())c.setReadOnly(!editable);Div grid=new Div(habilitado,venta,linea,porcentaje,monto,motivo,autorizacion);grid.addClassName("cc-surcharge-policy-grid");AppActionButton guardar=new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Guardar",e->{try{datos=service.guardarPolitica(new ConfiguracionRecargoInput(habilitado.getValue(),venta.getValue(),linea.getValue(),porcentaje.getValue(),monto.getValue(),motivo.getValue(),autorizacion.getValue(),datos.version()));cargar();Notification.show("Configuración guardada correctamente.");}catch(RuntimeException ex){error(ex,"No fue posible guardar la configuración.");}});guardar.setVisible(editable);Div acciones=new Div(guardar);acciones.addClassName("cc-form-actions");return seccion("POLÍTICA GENERAL",grid,acciones);}
 private Component limites(){gridLimites.removeAllColumns();gridLimites.addColumn(ConfiguracionRecargoDto.Limite::rol).setHeader("Rol").setFlexGrow(1);gridLimites.addColumn(x->x.porcentajeMaximo()==null?"Sin límite":x.porcentajeMaximo().stripTrailingZeros()+"%").setHeader("Máximo %").setTextAlign(ColumnTextAlign.END);gridLimites.addColumn(x->x.montoMaximo()==null?"Sin límite":datos.monedaBase()+" "+money(x.montoMaximo())).setHeader("Máximo monto").setTextAlign(ColumnTextAlign.END);if(can("recargos_configuracion.editar"))gridLimites.addComponentColumn(x->new AppActionButton(ActionType.EDIT,ButtonSize.GRID_ACTION,"Editar límite",e->formLimite(x))).setHeader("Acciones");gridLimites.setItems(datos.limites());AppActionButton add=new AppActionButton(ActionType.NEW,ButtonSize.MAIN,"Agregar límite",e->formLimite(null));add.setVisible(can("recargos_configuracion.editar"));return seccionAccion("LÍMITES POR ROL",add,gridLimites);}
 private Component tipos(){gridTipos.removeAllColumns();gridTipos.addColumn(ConfiguracionRecargoDto.Tipo::nombre).setHeader("Nombre").setFlexGrow(1);gridTipos.addColumn(x->x.tipoPredeterminado()==TipoRecargoVenta.PERCENTAGE?"Porcentaje":"Monto").setHeader("Tipo");gridTipos.addColumn(x->x.valorPredeterminado()==null?"—":money(x.valorPredeterminado())+(x.tipoPredeterminado()==TipoRecargoVenta.PERCENTAGE?"%":"")).setHeader("Valor predet.");gridTipos.addColumn(x->x.activo()?"Activo":"Inactivo").setHeader("Estado");if(can("recargos_configuracion.editar"))gridTipos.addComponentColumn(x->new AppActionButton(ActionType.EDIT,ButtonSize.GRID_ACTION,"Editar tipo de recargo",e->formTipo(x))).setHeader("Acciones");gridTipos.setItems(datos.tipos());AppActionButton add=new AppActionButton(ActionType.NEW,ButtonSize.MAIN,"Agregar tipo de recargo",e->formTipo(null));add.setVisible(can("recargos_configuracion.editar"));return seccionAccion("TIPOS DE RECARGO",add,gridTipos);}
 private Component motivos(){gridMotivos.removeAllColumns();gridMotivos.addColumn(ConfiguracionRecargoDto.Motivo::nombre).setHeader("Motivo").setFlexGrow(1);gridMotivos.addColumn(x->x.activo()?"Activo":"Inactivo").setHeader("Estado");if(can("recargos_configuracion.editar"))gridMotivos.addComponentColumn(x->new AppActionButton(ActionType.EDIT,ButtonSize.GRID_ACTION,"Editar motivo",e->formMotivo(x))).setHeader("Acciones");gridMotivos.setItems(datos.motivos());AppActionButton add=new AppActionButton(ActionType.NEW,ButtonSize.MAIN,"Agregar motivo",e->formMotivo(null));add.setVisible(can("recargos_configuracion.editar"));return seccionAccion("MOTIVOS DE RECARGO",add,gridMotivos);}
 private void formLimite(ConfiguracionRecargoDto.Limite a){Dialog d=dialog(a==null?"AGREGAR LÍMITE":"EDITAR LÍMITE");ComboBox<ConfiguracionRecargoDto.RolOpcion> rol=new ComboBox<>("Rol");rol.setItems(datos.roles());rol.setItemLabelGenerator(ConfiguracionRecargoDto.RolOpcion::nombre);rol.setWidthFull();TextField pct=numero("Máximo porcentaje sin autorización"),imp=numero("Máximo monto sin autorización ("+datos.monedaBase()+")");Checkbox activo=new Checkbox("Activo",true);if(a!=null){rol.setValue(datos.roles().stream().filter(x->x.id().equals(a.rolId())).findFirst().orElse(null));rol.setReadOnly(true);valor(pct,a.porcentajeMaximo());valor(imp,a.montoMaximo());activo.setValue(a.activo());}d.add(rol,pct,imp,activo);guardar(d,()->service.guardarLimite(a==null?null:a.id(),new LimiteRecargoInput(rol.getValue()==null?null:rol.getValue().id(),parse(pct),parse(imp),activo.getValue(),a==null?null:a.version())));d.open();}
 private void formTipo(ConfiguracionRecargoDto.Tipo a){Dialog d=dialog(a==null?"AGREGAR TIPO DE RECARGO":"EDITAR TIPO DE RECARGO");TextField nombre=new TextField("Nombre"),valor=numero("Valor predeterminado");nombre.setWidthFull();ComboBox<TipoRecargoVenta> tipo=new ComboBox<>("Tipo predeterminado");tipo.setItems(TipoRecargoVenta.values());tipo.setItemLabelGenerator(x->x==TipoRecargoVenta.PERCENTAGE?"Porcentaje":"Monto");ComboBox<TratamientoFiscalRecargo> fiscal=new ComboBox<>("Tratamiento fiscal");fiscal.setItems(TratamientoFiscalRecargo.values());fiscal.setItemLabelGenerator(x->switch(x){case FOLLOW_LINE->"Según configuración fiscal de la línea";case TAXABLE->"Gravado";case EXEMPT->"Exento";});Checkbox editable=new Checkbox("Permitir modificar el valor",true),activo=new Checkbox("Activo",true);if(a!=null){nombre.setValue(a.nombre());tipo.setValue(a.tipoPredeterminado());valor(valor,a.valorPredeterminado());fiscal.setValue(a.tratamientoFiscal());editable.setValue(a.valorEditable());activo.setValue(a.activo());}else fiscal.setValue(TratamientoFiscalRecargo.FOLLOW_LINE);d.add(nombre,tipo,valor,fiscal,editable,activo);guardar(d,()->service.guardarTipo(a==null?null:a.id(),new TipoRecargoInput(nombre.getValue(),tipo.getValue(),parse(valor),fiscal.getValue(),editable.getValue(),activo.getValue(),a==null?null:a.version())));d.open();}
 private void formMotivo(ConfiguracionRecargoDto.Motivo a){Dialog d=dialog(a==null?"AGREGAR MOTIVO":"EDITAR MOTIVO");TextField nombre=new TextField("Nombre");nombre.setWidthFull();Checkbox otro=new Checkbox("Solicitar detalle cuando se utilice"),activo=new Checkbox("Activo",true);if(a!=null){nombre.setValue(a.nombre());otro.setValue(a.otro());activo.setValue(a.activo());}d.add(nombre,otro,activo);guardar(d,()->service.guardarMotivo(a==null?null:a.id(),new MotivoRecargoInput(nombre.getValue(),otro.getValue(),activo.getValue(),a==null?null:a.version())));d.open();}
 private void guardar(Dialog d,Runnable r){d.getFooter().add(new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Guardar",e->{try{r.run();d.close();construir();Notification.show("Registro guardado correctamente.");}catch(RuntimeException ex){error(ex,"No fue posible guardar el registro.");}}),new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));}
 private void cargar(){habilitado.setValue(datos.habilitado());venta.setValue(datos.permiteVenta());linea.setValue(datos.permiteLinea());porcentaje.setValue(datos.permitePorcentaje());monto.setValue(datos.permiteMonto());motivo.setValue(datos.requiereMotivo());autorizacion.setValue(datos.permiteAutorizacion());disponibilidad();}private void disponibilidad(){boolean x=habilitado.getValue()&&can("recargos_configuracion.editar");for(Checkbox c:List.of(venta,linea,porcentaje,monto,motivo,autorizacion))c.setEnabled(x);}private List<Checkbox> campos(){return List.of(habilitado,venta,linea,porcentaje,monto,motivo,autorizacion);}
 private static Div seccion(String t,Component... c){Div d=new Div();d.addClassName("cc-form-section");d.add(new H3(t));d.add(c);return d;}private static Div seccionAccion(String t,Component a,Component c){Div h=new Div(new H3(t),a);h.addClassName("cc-section-header-actions");Div d=new Div(h,c);d.addClassName("cc-form-section");return d;}private static Dialog dialog(String t){Dialog d=new Dialog();d.setHeaderTitle(t);d.setWidth("min(560px,94vw)");d.setCloseOnOutsideClick(false);return d;}private static TextField numero(String l){TextField f=new TextField(l);f.setPlaceholder("0.00");f.setWidthFull();return f;}private static BigDecimal parse(TextField f){String x=f.getValue()==null?"":f.getValue().replace(",","").trim();if(x.isEmpty())return null;try{return new BigDecimal(x);}catch(NumberFormatException e){throw new ReglaNegocioException("Ingresa un valor numérico válido.");}}private static void valor(TextField f,BigDecimal v){f.setValue(v==null?"":v.stripTrailingZeros().toPlainString());}private static String money(BigDecimal v){return String.format(Locale.US,"%,.2f",v);}private static boolean can(String p){return TenantContext.principalActual().permisos().contains(p);}private static void error(RuntimeException e,String f){com.citacloud.springboot.contacloud.app.errors.UiErrorHandler.show(e,f);}}
